// Detect STOP (case-insensitive word boundary) in subject/body.
// Parse InvoiceID from subject/body when present; else fall back to ClientEmail + Open match downstream.
function wordStop(text) {
  return /\bSTOP\b/i.test(String(text || ''));
}

function extractInvoiceId(text) {
  const s = String(text || '');
  // Prefer explicit InvoiceID: INV-123 / invoice INV-123 / InvoiceID=INV-123
  let m = /\bInvoiceID\s*[:=]\s*([A-Za-z0-9._-]+)/i.exec(s);
  if (m) return m[1];
  m = /\binvoice\s+#?\s*([A-Za-z0-9._-]+)/i.exec(s);
  if (m) return m[1];
  m = /\b(INV-[A-Za-z0-9._-]+)\b/i.exec(s);
  if (m) return m[1];
  return '';
}

const out = [];
for (const item of items) {
  const j = item.json;
  const subject = j.subject || j.Subject || '';
  const body = j.textPlain || j.text || j.snippet || j.body || '';
  const html = j.textHtml || j.html || '';
  const combined = [subject, body, html].join('\n');
  if (!wordStop(combined)) continue;

  const from = String(j.from || j.From || j.sender || '').trim();
  // Extract bare email from "Name <email@x>"
  const em = /([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/.exec(from);
  const clientEmail = em ? em[1].toLowerCase() : from.toLowerCase();
  const invoiceId = extractInvoiceId(combined);

  out.push({
    json: {
      stopDetected: true,
      InvoiceID: invoiceId,
      ClientEmail: clientEmail,
      matchedBy: invoiceId ? 'invoiceId' : 'clientEmail',
      receivedAt: new Date().toISOString(),
      noteLine: '', // filled after match
    }
  });
}
return out;

// Match STOP reply to a sheet row: InvoiceID if present, else ClientEmail + Status=Open.
// Sets Status=Paused and appends Notes with timestamp "STOP received".
// Main chase Compute Stage skips Paused → remaining 0/+3/+7 sends are cancelled.
const stopItem = $('Detect STOP + Parse InvoiceID').first().json;
const wantId = String(stopItem.InvoiceID || '').trim();
const wantEmail = String(stopItem.ClientEmail || '').trim().toLowerCase();
const stamp = stopItem.receivedAt || new Date().toISOString();
const noteAppend = `[${stamp}] STOP received`;

const matches = [];
for (const item of items) {
  const row = item.json;
  const id = String(row.InvoiceID || '').trim();
  const email = String(row.ClientEmail || '').trim().toLowerCase();
  const status = String(row.Status || '').trim();

  let hit = false;
  if (wantId && id.toLowerCase() === wantId.toLowerCase()) {
    hit = true;
  } else if (!wantId && wantEmail && email === wantEmail && status === 'Open') {
    hit = true;
  }
  if (!hit) continue;

  const prevNotes = String(row.Notes || '').trim();
  const notes = prevNotes ? `${prevNotes} | ${noteAppend}` : noteAppend;

  matches.push({
    json: {
      InvoiceID: id,
      Status: 'Paused',
      Notes: notes,
      matchedBy: wantId ? 'invoiceId' : 'clientEmail+Open',
    }
  });
}

// If multiple Open rows share one email and no InvoiceID, pause all matched Open rows
// (safer opt-out than guessing a single invoice).
return matches;
